import * as T from './vendor/three.module.js';
import {ANIMAL_MOTION_CATALOG} from './animal-motion-catalog.js';
import {createAnimalPaint} from './animal-motion-paint.js';
import {createRedHatCap} from './red-hat-model.js';
import {LIGHT_ATLAS} from './horse-light-model.js';
import {createCliffClimb,CLIFF_CLIMB_PHASES} from './cliff-climb.js';
import {createCliffTiles} from './cliff-tiles.js';
import {createPaintedGrass} from './painted-grass.js';
const $=id=>document.getElementById(id),params=new URLSearchParams(location.search),profile=ANIMAL_MOTION_CATALOG.find(p=>p.id==='horse');
for(const id of ['outfit','view','scale'])if(params.has(id))$(id).value=params.get(id);
const renderer=new T.WebGLRenderer({canvas:$('scene'),antialias:true,preserveDrawingBuffer:true});renderer.setPixelRatio(1);renderer.setSize(1400,850,false);renderer.setClearColor('#303b33');renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;
const scene=new T.Scene(),camera=new T.OrthographicCamera(),loader=new T.TextureLoader();scene.add(new T.HemisphereLight(0xfff1d3,0x778878,2));const sun=new T.DirectionalLight(0xffecd5,2.4);sun.position.set(-4,8,-5);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.normalBias=.012;Object.assign(sun.shadow.camera,{left:-6,right:6,top:6,bottom:-6});scene.add(sun);
const ground=new T.Mesh(new T.PlaneGeometry(24,24),createPaintedGrass());ground.rotation.x=-Math.PI/2;ground.position.y=-.01;ground.receiveShadow=true;scene.add(ground);
const tiles=[];for(let x=0;x<3;x++)for(let z=-2;z<2;z++)tiles.push({x,z,mask:15,variant:0});const cliff=createCliffTiles('ledge',tiles);scene.add(cliff.root);
const dots=new T.Group();scene.add(dots);const markers=Array.from({length:4},()=>{const m=new T.Mesh(new T.SphereGeometry(.025,10,8),new T.MeshBasicMaterial({color:0xf5e987,depthTest:false}));m.renderOrder=4;dots.add(m);return m;});
let worker,paint,cap,motion,loading=false,playing=false,last=0,progress=0;
function disposeActor(){if(!worker)return;scene.remove(worker.root);motion?.dispose();cap?.dispose();paint?.dispose();worker.skeleton.dispose();worker.dispose();worker=paint=cap=motion=null;}
const texture=await loader.loadAsync(LIGHT_ATLAS);texture.colorSpace=T.SRGBColorSpace;
async function load(){if(loading)return;loading=true;playing=false;$('play').textContent='Play';window.cliffClimbStudy.ready=false;const outfit=$('outfit').value;try{disposeActor();const response=await fetch(profile.file);if(!response.ok)throw Error('Horse mesh failed to load');worker=profile.create(await response.json(),texture);paint=await createAnimalPaint(renderer,worker,profile,loader,outfit);for(const p of worker.parts){p.material=paint.material;p.castShadow=p.receiveShadow=true;}cap=outfit==='red-hats'?await createRedHatCap(renderer,worker,profile,loader):null;motion=createCliffClimb(worker,profile);scene.add(worker.root);window.cliffClimbStudy.ready=true;render();}catch(e){$('status').textContent=e.message;console.error(e);}finally{loading=false;if(outfit!==$('outfit').value)load();}}
function render(){if(!motion)return;const d=motion.apply(progress),scale={full:180,close:310,game:58}[$('scale').value],center=$('scale').value==='close'?new T.Vector3(d.root[0]+.15,d.root[1]+1,0):new T.Vector3(.4,1.85,0),view={three:[-1,.38,1.4],side:[0,.12,1],front:[1,.3,0],rear:[-1,.22,0]}[$('view').value];
for(const p of worker.parts)p.material=$('grey').checked?worker.grey:paint.material;camera.left=-700/scale;camera.right=700/scale;camera.top=425/scale;camera.bottom=-425/scale;camera.near=.01;camera.far=80;camera.position.copy(center).add(new T.Vector3(...view).multiplyScalar(8));camera.lookAt(center);camera.updateProjectionMatrix();dots.visible=$('contacts').checked;const c=d.contacts.filter(c=>c.point);markers.forEach((m,i)=>{m.visible=!!c[i];if(c[i]){m.position.fromArray(c[i].worldPoint||c[i].point);m.material.color.set(c[i].planted?0x9beb83:0xffb265);}});renderer.render(scene,camera);$('progress').value=progress;$('time').textContent=`${(progress*6).toFixed(2)} / 6.00 s`;$('status').textContent=d.phase;Object.assign(window.cliffClimbStudy,{worker,motion,result:d});}
window.cliffClimbStudy={ready:false,renderer,scene,camera,cliff,seek(p){playing=false;$('play').textContent='Play';progress=T.MathUtils.clamp(p,0,1);render();},render};
for(const p of CLIFF_CLIMB_PHASES){const b=document.createElement('button');b.textContent=p.label;b.onclick=()=>window.cliffClimbStudy.seek((p.start+p.end)/12);$('phases').append(b);}
$('outfit').onchange=load;for(const id of ['view','scale','grey','contacts'])$(id).oninput=render;$('progress').oninput=()=>window.cliffClimbStudy.seek(+$('progress').value);$('play').onclick=()=>{playing=!playing;$('play').textContent=playing?'Pause':'Play';if(progress===1)progress=0;last=performance.now();};
let frame;function animate(now){if(playing&&motion){progress=Math.min(1,progress+Math.min(.1,(now-last)/1000)/6);render();if(progress===1){playing=false;$('play').textContent='Play';}}last=now;frame=requestAnimationFrame(animate);}frame=requestAnimationFrame(animate);addEventListener('pagehide',()=>{cancelAnimationFrame(frame);disposeActor();cliff.dispose();texture.dispose();ground.geometry.dispose();ground.material.dispose();markers.forEach(m=>{m.geometry.dispose();m.material.dispose();});renderer.dispose();},{once:true});load();
